--- tests/asd/intune/Test.ASD.ISM-1488.ps1
Title = 'Microsoft Office macros in files originating from the internet are blocked.'
Control = ('essential-eight:ISM-1488', 'nist-800-53-r5:CM-7'),
    param()

    $applications = [ordered]@{
        Word       = 'user_vendor_msft_policy_config_word16v'
        Excel      = 'user_vendor_msft_policy_config_excel16v'
        PowerPoint = 'user_vendor_msft_policy_config_ppt16v'
        Access     = 'user_vendor_msft_policy_config_access16v'
        Visio      = 'user_vendor_msft_policy_config_visio16v'
        Project    = 'user_vendor_msft_policy_config_proj16v'
        Publisher  = 'user_vendor_msft_policy_config_pub16v'
    }
    $required = @('Word', 'Excel', 'PowerPoint')

    $rows = @(Get-MtIntuneConfigurationPolicySetting | Where-Object { $_.SettingDefinitionId -like '*_l_blockmacroexecutionfrominternet' })

    $report = foreach ($application in $applications.Keys) {
        $settings = @($rows | Where-Object { $_.SettingDefinitionId.StartsWith($applications[$application], [System.StringComparison]::OrdinalIgnoreCase) })
        $blocking = @($settings | Where-Object { $_.IsAssigned -and [string]$_.Value -like '*_1' })
        [pscustomobject]@{
            Application = $application
            Required    = $application -in $required
            Blocked     = $blocking.Count -gt 0
            Policies    = @($blocking.PolicyName | Sort-Object -Unique) -join ', '
            Configured  = $settings.Count -gt 0
        }
--- tests/asd/intune/Test.ASD.ISM-1654.ps1
Title = 'Internet Explorer 11 is disabled or removed.'
Control = ('essential-eight:ISM-1654', 'nist-800-53-r5:CM-7'),
    param()

    $rows = @(Get-MtIntuneConfigurationPolicySetting | Where-Object { $_.SettingDefinitionId -match '_internetexplorer_disableinternetexplorerapp(_v\d+)?$' })
    $report = foreach ($row in $rows) {
        [pscustomobject]@{ Policy = $row.PolicyName; Enabled = [string]$row.Value -like '*_1'; Assigned = $row.IsAssigned }
    }
    $testResult = @($report | Where-Object { $_.Enabled -and $_.Assigned }).Count -gt 0

    if ($rows.Count -eq 0) {
        $testResultMarkdown = 'No Intune Windows policy configures **Disable Internet Explorer 11 as a standalone browser**. Enable it in a settings catalog policy assigned to your workstations, or remove the Internet Explorer optional feature.'
    } else {
        $table = "| Policy | Setting | Assigned |`n| --- | --- | --- |`n"
        foreach ($r in $report) { $table += "| $($r.Policy) | $(if ($r.Enabled) { 'Enabled' } else { 'Disabled' }) | $(if ($r.Assigned) { 'Yes' } else { 'No' }) |`n" }
        if ($testResult) {
            $testResultMarkdown = "Well done. An assigned Intune policy disables Internet Explorer 11 as a standalone browser.`n`n$table"
        } else {
            $testResultMarkdown = "The setting is configured, but no assigned policy enables it.`n`n$table"
        }
    }
    Add-MtTestResultDetail -Result $testResultMarkdown
    return $testResult
}
--- tests/asd/intune/Test.ASD.ISM-1667.ps1
Title = 'Microsoft Office is blocked from creating child processes.'
Control = ('essential-eight:ISM-1667', 'nist-800-53-r5:CM-7'),
    param()

    return Test-MtAsdAsrRule -RuleSuffix 'blockallofficeapplicationsfromcreatingchildprocesses' -RuleName 'Block all Office applications from creating child processes'
