Control = ('essential-eight:ISM-1654', 'nist-800-53-r5:CM-7'),
    param()

    $rows = @(Get-MtIntuneConfigurationPolicySetting | Where-Object { $_.SettingDefinitionId -match '_internetexplorer_disableinternetexplorerapp(_v\d+)?$' })
